import { useState } from 'react';
import { Button, Modal } from '@mantine/core';
import { isEmail, isNotEmpty, useForm } from '@mantine/form';
import { useDisclosure } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';
import { User, UserValues } from './types';
import { UserForm } from './UserForm';
import { UsersTable } from './UsersTable';

function createUser(values: UserValues) {
  return new Promise<User>((resolve) => {
    setTimeout(() => resolve({ ...values, id: Date.now() }), 1000);
  });
}

export function FormInModal() {
  const [opened, { open, close }] = useDisclosure(false);
  const [users, setUsers] = useState<User[]>([]);

  const form = useForm<UserValues>({
    initialValues: {
      name: '',
      email: '',
      role: null,
    },
    validate: {
      name: isNotEmpty('Name is required'),
      email: isEmail('Invalid email'),
      role: isNotEmpty('Select a role'),
    },
  });

  const handleClose = () => {
    form.reset();
    close();
  };

  const handleSubmit = async (values: UserValues) => {
    const user = await createUser(values);
    setUsers((current) => [...current, user]);
    notifications.show({ title: 'User added', message: `${user.name} added as ${user.role}` });
    handleClose();
  };

  return (
    <>
      <Modal
        opened={opened}
        onClose={handleClose}
        title="Add user"
        closeOnClickOutside={!form.submitting}
        closeOnEscape={!form.submitting}
        withCloseButton={!form.submitting}
      >
        <form onSubmit={form.onSubmit(handleSubmit)}>
          <UserForm form={form} onCancel={handleClose} />
        </form>
      </Modal>

      <Button onClick={open}>Add user</Button>
      <UsersTable users={users} />
    </>
  );
}

import { Button, Group, Select, Stack, TextInput } from '@mantine/core';
import { UseFormReturnType } from '@mantine/form';
import { UserValues } from './types';

interface UserFormProps {
  form: UseFormReturnType<UserValues>;
  onCancel: () => void;
}

export function UserForm({ form, onCancel }: UserFormProps) {
  return (
    <Stack>
      <TextInput
        label="Name"
        placeholder="John Doe"
        withAsterisk
        data-autofocus
        {...form.getInputProps('name')}
      />

      <TextInput
        label="Email"
        placeholder="john@mantine.dev"
        withAsterisk
        {...form.getInputProps('email')}
      />

      <Select
        label="Role"
        placeholder="Pick role"
        withAsterisk
        data={['Admin', 'Editor', 'Viewer']}
        {...form.getInputProps('role')}
      />

      <Group justify="flex-end" mt="md">
        <Button variant="default" onClick={onCancel} disabled={form.submitting}>
          Cancel
        </Button>

        <Button type="submit" loading={form.submitting}>
          Add user
        </Button>
      </Group>
    </Stack>
  );
}

import { Table, Text } from '@mantine/core';
import { User } from './types';

interface UsersTableProps {
  users: User[];
}

export function UsersTable({ users }: UsersTableProps) {
  if (users.length === 0) {
    return (
      <Text size="xs" mt="md">
        No users yet
      </Text>
    );
  }

  const rows = users.map((user) => (
    <Table.Tr key={user.id}>
      <Table.Td>{user.name}</Table.Td>
      <Table.Td>{user.email}</Table.Td>
      <Table.Td>{user.role}</Table.Td>
    </Table.Tr>
  ));

  return (
    <Table mt="md">
      <Table.Thead>
        <Table.Tr>
          <Table.Th>Name</Table.Th>
          <Table.Th>Email</Table.Th>
          <Table.Th>Role</Table.Th>
        </Table.Tr>
      </Table.Thead>
      <Table.Tbody>{rows}</Table.Tbody>
    </Table>
  );
}

export interface UserValues {
  name: string;
  email: string;
  role: string | null;
}

export interface User extends UserValues {
  id: number;
}
